export default function prepare({ title, image }) {
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text: `Focus on the ${title} in the image. Describe the object, its model or make, material, color, and condition (poor, good, excellent). Leave uncertain attributes blank.`,
          },
          { type: "input_image", image_url: image },
        ],
      },
    ],
  };
}

n_b1e063975bf51707.source:
export default function read({ response }) {
  if (response?.status && response.status !== "completed") throw Error("Image analysis incomplete");
  const text =
    response?.output_text ??
    response?.output?.flatMap((x) => x.content ?? []).find((x) => x.type === "output_text")?.text;
  if (typeof text !== "string" || !text.trim()) throw Error("Image analysis empty");
  return { description: text };
}

n_65343f64ae2d2d75.source:
export default function prepare({ id, answer }) {
  const fields = {};
  for (const [a, b] of Object.entries({
    title: "Title",
    description: "Description",
    model: "Model",
    material: "Material",
    color: "Color",
    condition: "Condition",
  })) {
    if (typeof answer?.[a] !== "string") throw Error("Invalid model output");
    fields[b] = answer[a];
  }
  fields.AI_status = true;
  return { records: [{ id, fields }] };
}

n_2f60e464410bebd3.source:
export default function read({ body, statusCode }) {
  if (statusCode < 200 || statusCode >= 300 || !Array.isArray(body?.image_results))
    throw Error("Reverse image search failed");
  return {
    response: JSON.stringify(
      body.image_results.map((x) => ({
        position: x.position,
        title: x.title,
        link: x.link,
        description: x.snippet,
      })),
    ),
  };
}

n_edb6e5c1e5130acf.source:
export default function read({ output }) {
  return {
    response:
      output?.success && typeof output.data?.markdown === "string"
        ? output.data.markdown.substring(0, 3000)
        : '{ error: "Unable to scrape website due to unknown error. Do not retry." }',
  };
}
